mapper.select:
SELECT COALESCE(SUM(CAST(DISCOUNT_AMOUNT * 100 AS BIGINT)), 0)
FROM orders_legacy
WHERE MERCHANT_ID = #{storeId}
  AND CREATE_TIME >= #{startTime}
  AND CREATE_TIME < #{endTime}
  AND ORDER_STATUS IN (1, 4)
  AND DELETED = 0

SELECT
    COALESCE(SUM(CAST(REFUND_AMOUNT * 100 AS BIGINT)), 0) AS total_refund_amount,
    COUNT(*) AS refund_count
FROM orders_legacy
WHERE MERCHANT_ID = #{storeId}
  AND CREATE_TIME >= #{startTime}
  AND CREATE_TIME < #{endTime}
  AND ORDER_STATUS = 7
  AND DELETED = 0

SELECT
    COALESCE(SUM(CAST(ORDER_AMOUNT * 100 AS BIGINT)), 0) AS total_cancelled_amount,
    COUNT(*) AS cancelled_count
FROM orders_legacy
WHERE MERCHANT_ID = #{storeId}
  AND CREATE_TIME >= #{startTime}
  AND CREATE_TIME < #{endTime}
  AND ORDER_STATUS = 5
  AND DELETED = 0
